#include <deque>
template <typename T, typename Allocator = std::allocator<T>>
class MyDequeWrapper {
public:
    std::deque<T, Allocator> data;
    void add(const T& value) { data.push_back(value); }
    T getFront() const { return data.front(); }
};
int main() {
    MyDequeWrapper<int> myDeque; // Uses default allocator
    myDeque.add(10);
    int frontValue = myDeque.getFront();
    return 0;
}
